+/** The settings' choice, else the chat's own provider and model. */
+export function plannerProvider(
+	settings: Settings,
+	chat?: { providerId: string; modelId: string },
+): ProviderChoice {
+	const model = settings.planner.model;
+	if (model.kind === "model")
