+		outputTokens: (total?.outputTokens ?? 0) + chunk.outputTokens,
+		cacheReadTokens:
+			(total?.cacheReadTokens ?? 0) + (chunk.cacheReadTokens ?? 0),
+		cacheWriteTokens:
+			(total?.cacheWriteTokens ?? 0) + (chunk.cacheWriteTokens ?? 0),
+	};
+}
