+		else if (chunk.type === "usage") {
+			usage = addUsage(usage, chunk);
+			if (chunk.totalCost !== undefined)
+				costUsd = (costUsd ?? 0) + chunk.totalCost;
+		} else if (chunk.type === "done" && !chunk.success)
